'use strict'

// Polyfill: make electron-store work in renderer (require('electron').app is not available without enableRemoteModule)
try {
	const electron = require( 'electron' )
	const remote = require( '@electron/remote' )
	if( !electron.app ) {
		electron.app = remote.app
	} else {
		// electron.app already defined
	}
} catch( e ) {
	// polyfill failed
}

const log			= require( 'electron-log' )

const i18n = require( './i18n.min' )
const { ipcRenderer, shell } = require( 'electron' )
const Store			= require( 'electron-store' )
let store
try {
	store = new Store()
} catch(e) {
	log.error( 'renderer: Store creation failed: ' + e.message )
}
const $				= require( 'jquery' )
const generate		= require( 'string-to-color' )

const path			= require( 'path' )
const fetch			= require( './fetch.min' )
const maintable		= require( './bookmark-table.min' )
const dates			= require( './dates.min' )
const modalWindow	= require( './modal.min' )
const exp 			= require( './export.min' )
const entities 		= require( './entities.min' )
const folderList	= require( './folder-list.min' )
const serialize		= require( './serialize.min' )
const previews		= require( './previews.min' )
const jqueryI18next = require( 'jquery-i18next' )
jqueryI18next.init(i18n, $)

let server 		= store.get( 'loginCredentials.server' ),
	username 	= store.get( 'loginCredentials.username' ),
	password 	= store.get( 'loginCredentials.password' ),
	firstLoad 	= true,
	modal,
	total

//note(dgmid): store for bookmarks

let bookmarks	= new Store( {name: 'bookmarks'} )



//note(dgmid): locale-aware folder name comparison (case / accent / Ñ-insensitive).
//Plain code-point compares put "Ávila" after "zoo" and misplace capitals, which
//makes alphabetised folder lists look wrong for Spanish and other Latin scripts.

const _cmpCollator = ( typeof Intl !== 'undefined' && Intl.Collator )
	? new Intl.Collator( undefined, { numeric: true, sensitivity: 'base' } )
	: null

function _cmpNameObjects( a, b ) {
	
	if( _cmpCollator ) return _cmpCollator.compare( a.text, b.text )
	
	let x = String( a.text ).toLowerCase(),
		y = String( b.text ).toLowerCase()
	
	return ( x > y ) ? 1 : ( ( x < y ) ? -1 : 0 )
}



//note(dgmid): degraded (read-only) mode — the server rejected the session (401/403).
//Show a banner and keep working from the local mirror; fetch.js blocks writes.

function showDegradedBanner() {
	
	$('#degraded-banner').addClass('visible')
	$('#degraded-banner .degraded-text').html( i18n.t('app:degraded.banner', 'Server offline or session rejected — read-only mode. Your bookmarks are safe in the local copy.') )
}

function hideDegradedBanner() {
	
	$('#degraded-banner').removeClass('visible')
}

//note(dgmid): status changes sent by fetch.js from any window (this is the main one)
ipcRenderer.on('server-status-changed', (event, status) => {
	
	if( status && status.degraded ) showDegradedBanner()
	else hideDegradedBanner()
})



//note(dgmid): fetch folders + all bookmarks from the server. If the server rejects
//the session (degraded mode), fall back to the local mirror so the app stays
//usable (read-only) instead of showing an empty table.

function loadBookmarks() {
	
	loader( 'add' )
	showSync()
	
	fetch.bookmarksApi( 'folders', '', '', function() {
		
		fetch.bookmarksApi( 'all', '', '', function( array ) {
			
			if( !Array.isArray( array ) ) {
				
				hideSync()
				
				//note(dgmid): server unreachable — load the last known mirror from disk
				if( store.get( '_serverDegraded' ) ) {
					
					let cached = bookmarks.get( 'data' )
					
					if( Array.isArray( cached ) && cached.length > 0 ) {
						
						log.info( `degraded mode: loaded ${cached.length} bookmarks from the local mirror` )
						parseBookmarks( cached )
						
					} else {
						
						log.warn( 'degraded mode: no local mirror available' )
					}
					
					showDegradedBanner()
				}
				
				return
			}
			
			parseBookmarks( array )
		})
	})
}



//note(dgmid): continue offline — no credentials needed. Load the local mirror in
//read-only mode so the user can browse, search and export until the server is
//reachable again (triggered by the login modal's "Continue offline" button).

function loadOfflineMirror() {
	
	loader( 'add' )
	
	//note(dgmid): block writes exactly like the server-rejection path
	store.set( '_serverDegraded', true )
	showDegradedBanner()
	
	let cached = bookmarks.get( 'data' )
	
	if( Array.isArray( cached ) && cached.length > 0 ) {
		
		log.info( `offline mode: loaded ${cached.length} bookmarks from the local mirror` )
		parseBookmarks( cached )
		
	} else {
		
		loader( 'remove' )
		log.warn( 'offline mode: no local mirror available' )
	}
}

//note(dgmid): the user chose "Continue offline" in the login modal
ipcRenderer.on('continue-offline', (event, message) => {
	
	loadOfflineMirror()
})



//note(dgmid): log exceptions

window.onerror = function( error, url, line ) {
	
	ipcRenderer.send( 'error-in-render', {error, url, line} )
}



//note(dgmid): populate dataTable

function parseBookmarks( array ) {
	
	total = array.length
	_rawBookmarks = array
	
	let folderList	= store.get( 'folders' ),
		allTags 	= [],
		noTag 		= i18n.t('app:sidebar.filter.untagged', 'un-tagged')
	
	//note(dgmid): collect unique tag names for the sidebar counts
	for ( let item of array ) {
		
		let uniqueTags = Array.from( new Set( item.tags ) )
		if( uniqueTags.length < 1 ) { uniqueTags.push( noTag ) }
		
		for ( let tagitem of uniqueTags ) {
			allTags.push( tagitem )
		}
	}
	
	//note(dgmid): Phase 2 — INCREMENTAL rebuild. Diff the new payload against the rows
	//already in the table (by id) and touch only what changed, in ONE batched draw.
	//This keeps sort order, selection and scroll position intact and avoids the cost
	//of clear()+re-adding thousands of rows after every refresh.
	
	let table = maintable.bookmarkTable
	
	//note(dgmid): snapshot the rows currently in the table, keyed by bookmark id
	let currentRows = new Map()
	table.rows().every(function() {
		
		let d = this.data()
		currentRows.set( d[0], d )
	})
	
	let newIds = new Set( array.map( i => i.id ) )
	
	//note(dgmid): removals — ids present in the table but gone from the server
	let toRemove = []
	for( let [ id ] of currentRows ) {
		if( !newIds.has( id ) ) toRemove.push( id )
	}
	
	//note(dgmid): additions vs updates
	let toAdd 		= [],
		toAddIds 	= [],
		toUpdate 	= []
	
	for( let item of array ) {
		
		let row = buildRow( item, folderList, noTag )
		
		if( !currentRows.has( item.id ) ) {
			
			toAdd.push( row )
			if( item.id ) toAddIds.push( item.id )
			
		} else if( !sameRow( currentRows.get( item.id ), row ) ) {
			
			toUpdate.push( { id: item.id, row: row } )
		}
	}
	
	//note(dgmid): apply removals
	for( let id of toRemove ) {
		table.row( '#row_' + id ).remove()
	}
	
	//note(dgmid): apply updates
	for( let u of toUpdate ) {
		table.row( '#row_' + u.id ).data( u.row ).invalidate()
	}
	
	//note(dgmid): batch-add all new rows in one pass
	if( toAdd.length > 0 ) {
		table.rows.add( toAdd )
	}
	
	//note(dgmid): single batched draw applies removals + updates + additions together
	table.draw( false )
	
	//note(dgmid): (re)apply favicon images on the rows whose title cell changed
	let showFavicon = store.get('tableColumns.favicon')
	if( showFavicon === undefined ) showFavicon = true
	
	let dir = store.get('dirPath')
	if( dir ) {
		
		let tpath 		= 'file://' + encodeURI( path.join( __dirname, '../assets/png/faviconTemplate.png' ) ),
			displayStyle = showFavicon ? '' : 'display:none;'
		
		for( let id of toAddIds ) applyFaviconToRow( id, tpath, dir, displayStyle )
		for( let u of toUpdate ) applyFaviconToRow( u.id, tpath, dir, displayStyle )
	}
	
	buildFolderList( folderList )
	buildTagList( allTags.sort(), noTag )
	buildFolderStrip()
	
	hideSync()
	
	if( firstLoad === true ) {
		
		setColControls()
		
		const check = require( './version.min' )
		firstLoad = false
		check.appVersion()
	}
}



//note(dgmid): mirror of the last fetched bookmark array. Local operations (delete,
//move, edit, apply tags) update this copy so the sidebar counts and the table can be
//refreshed instantly without re-downloading the whole catalogue.

let _rawBookmarks = []



//note(dgmid): multi-tag filter state — a set of selected tag names combined with
//AND (all of them) or OR (any of them) logic. 'un-tagged' is a pseudo-tag meaning
//the bookmark has no real tags.

let _selectedTags 	= [],
	_tagMode 		= 'AND'



//note(dgmid): custom DataTable search plugin for multi-tag filtering. It inspects
//the raw bookmark's tags (from the local mirror) instead of the rendered HTML.
//Only applies to the main bookmarks table; other tables (e.g. details panels)
//are passed through untouched.

$.fn.dataTable.ext.search.push( function( settings, data, dataIndex, rowData ) {
	
	if( settings.nTable && settings.nTable.id !== 'bookmarks' ) return true
	if( _selectedTags.length === 0 ) return true
	
	//note(dgmid): read the bookmark id from the ORIGINAL row data (4th argument) —
	//the search-data array (2nd argument) has an EMPTY string at column 0 because
	//the hidden ID column is configured with searchable:false (_fnFilterData stores
	//'' there), so data[0] would be '' → parseInt('') → NaN → bookmark not found →
	//every row would pass and the tag filter would never filter.
	let id 	= parseInt( rowData[0], 10 ),
		bm 	= _rawBookmarks.find( b => b.id === id )
	
	if( !bm ) return true
	
	let tags 	= bm.tags || [],
		noTag 	= i18n.t('app:sidebar.filter.untagged', 'un-tagged')
	
	let results = _selectedTags.map( t => {
		
		if( t === noTag ) return tags.length === 0
		return tags.includes( t )
	})
	
	return _tagMode === 'AND' ? results.every( Boolean ) : results.some( Boolean )
})



//note(dgmid): multi-tag helpers — toggle a tag in the selection set, re-mark the
//sidebar rows and drive the AND/OR toolbar

function getTagFilterName( el ) {
	
	if( $(el).hasClass('untagged') ) return i18n.t('app:sidebar.filter.untagged', 'un-tagged')
	
	return entities.decode( $(el).data('filter') || '' )
}

function toggleTagSelection( el ) {
	
	let name 	= getTagFilterName( el ),
		idx 	= _selectedTags.indexOf( name )
	
	if( idx >= 0 ) _selectedTags.splice( idx, 1 )
	else _selectedTags.push( name )
	
	updateTagSelectionUI()
	maintable.bookmarkTable.draw()
	updateTagToolbar()
}

function updateTagSelectionUI() {
	
	let noTag = i18n.t('app:sidebar.filter.untagged', 'un-tagged')
	
	$('.filter.tagfilter').each( function() {
		
		$(this).toggleClass( 'selected', _selectedTags.includes( entities.decode( $(this).data('filter') || '' ) ) )
	})
	
	$('.filter.untagged').toggleClass( 'selected', _selectedTags.includes( noTag ) )
}

function updateTagToolbar() {
	
	$('#tag-mode-and').toggleClass( 'active', _tagMode === 'AND' )
	$('#tag-mode-or').toggleClass( 'active', _tagMode === 'OR' )
	$('#tag-clear').prop( 'disabled', _selectedTags.length === 0 )
}

$('#tag-mode-and').click( function() {
	
	_tagMode = 'AND'
	updateTagToolbar()
	maintable.bookmarkTable.draw()
})

$('#tag-mode-or').click( function() {
	
	_tagMode = 'OR'
	updateTagToolbar()
	maintable.bookmarkTable.draw()
})

$('#tag-clear').click( function() {
	
	_selectedTags = []
	updateTagSelectionUI()
	updateTagToolbar()
	maintable.bookmarkTable.draw()
})



//note(dgmid): build one row of table data from a raw bookmark object.
//Shared by the full parse (parseBookmarks) and by the instant local updates
//(delete / move / edit / apply tags) so the row looks identical either way.

function buildRow( item, folderList, noTag ) {
	
	let taglist = ''
	
	//note(dgmid): remove duplicate tags
	let uniqueTags = Array.from( new Set( item.tags ) )
	
	if( uniqueTags.length < 1 ) { uniqueTags.push( noTag ) }
	
	for ( let tagitem of uniqueTags ) {
	
		let color,
			untagged
		
		if( tagitem === noTag ) {
			
			color		 = ''
			untagged	 = ' untagged'
			
		} else {
			
			color		 = generate(tagitem)
			untagged	 = ''
		}
		
		taglist += `<span class="tag${untagged}" title="${entities.encode(tagitem)}" style="background-color: ${color};">${entities.encode(tagitem)}</span> <span class="tagname">${entities.encode(tagitem)}</span>`
	}
		
	let created 	= item.added,
		modified 	= item.lastmodified
	
	let theFolders = ''
	
	if( item.folders.length < 2 && item.folders[0] == -1 ) {
		
		theFolders = '⋯'
	
	} else {
		
		for( let folderItem of item.folders  ) {
			
			theFolders += '<span class="folder">'
			
			if( folderItem == -1 ) {
				
				theFolders += 'Home'
			
			} else {
			
				theFolders += folderList.find(x => x.id === folderItem).text
				
			}
			
			theFolders += '</span>'
			
		}
	}
	
	return [
		item.id,
		' ',
		( item.tags && item.tags.includes('broken') ? '⚠️ ' : '' ) + htmlEntities( item.title ),
		htmlEntities( item.description ),
		item.url,
		created,
		dates.columnDate( created ),
		modified,
		dates.columnDate( modified ),
		item.folders.join(','),
		theFolders,
		taglist
	]
}



//note(dgmid): deep-compare two table rows (used by the incremental rebuild to
//decide whether a row needs updating). Rows are plain arrays of primitives.
//Columns 6 and 8 are the RENDERED date strings ("today at 15:40" etc.) which
//change as the clock advances, so they're skipped — the raw unix timestamps in
//columns 5 and 7 are what actually reflect server-side changes. Skipping them
//keeps a refresh that crosses midnight from flagging every row as "changed".

function sameRow( a, b ) {
	
	if( a.length !== b.length ) return false
	
	for( let i = 0; i < a.length; i++ ) {
		
		if( i === 6 || i === 8 ) continue
		
		if( a[i] !== b[i] ) return false
	}
	
	return true
}



//note(dgmid): prepend a favicon image to a row's title cell (shared by the full
//parse, the incremental rebuild and the instant single-row updates)

function applyFaviconToRow( id, tpath, dir, displayStyle ) {
	
	let titleCell = maintable.bookmarkTable.cell( `#row_${id}`, 2 ).node()
	
	if( titleCell ) {
		
		let fpath = 'file://' + encodeURI( dir + '/favicons/' + id + '.png' )
		
		$(titleCell).prepend(
			`<img class="favicon-icon" src="${fpath}" onerror="this.src='${tpath}';this.onerror=null;" width="16" height="16" style="vertical-align:middle;margin-right:4px;${displayStyle}"> `
		)
	}
}



//note(dgmid): sync indicator — shown while a background reconciliation runs.
//The hide is delayed so even very fast refreshes give perceivable feedback
//instead of an imperceptible flash.

let _syncTimer 		= null,
	_syncMinVisible 	= 600

function showSync() {
	
	clearTimeout( _syncTimer )
	_syncTimer = null
	$('#sync-indicator').addClass('visible')
}

function hideSync() {
	
	//note(dgmid): already scheduled — keep the pill up until the minimum time elapses
	if( _syncTimer !== null ) return
	
	_syncTimer = setTimeout( function() {
		
		_syncTimer = null
		$('#sync-indicator').removeClass('visible')
		
	}, _syncMinVisible )
}



//note(dgmid): re-render a single table row from its raw bookmark object (instant local update)

function updateBookmarkRowLocal( item, refresh ) {
	
	let rowApi = maintable.bookmarkTable.rows( '#row_' + item.id )
	
	if( rowApi.count() > 0 ) {
		
		let row 		= maintable.bookmarkTable.row( '#row_' + item.id ),
			folderList	= store.get( 'folders' ),
			noTag 		= i18n.t('app:sidebar.filter.untagged', 'un-tagged')
		
		row.data( buildRow( item, folderList, noTag ) ).invalidate().draw( false )
		
		//note(dgmid): re-apply the favicon (the title cell was replaced by .data())
		let dir = store.get('dirPath')
		if( dir ) {
			
			let showFavicon 	= store.get('tableColumns.favicon'),
				displayStyle 	= ( showFavicon === undefined || showFavicon ) ? '' : 'display:none;',
				tpath 			= 'file://' + encodeURI( path.join( __dirname, '../assets/png/faviconTemplate.png' ) )
			
			applyFaviconToRow( item.id, tpath, dir, displayStyle )
		}
	}
	
	//note(dgmid): bulk callers pass refresh=false and call refreshSidebar() once at the end
	if( refresh !== false ) refreshSidebar()
}



//note(dgmid): drop a single table row (instant local update)

function removeBookmarkRowLocal( id, refresh ) {
	
	let rowApi = maintable.bookmarkTable.rows( '#row_' + id )
	
	if( rowApi.count() > 0 ) {
		
		maintable.bookmarkTable.row( '#row_' + id ).remove().draw( false )
	}
	
	//note(dgmid): bulk callers pass refresh=false and call refreshSidebar() once at the end
	if( refresh !== false ) refreshSidebar()
}



//note(dgmid): recompute sidebar counts (All bookmarks + tags) and the folder strip
//from the local mirror, without touching the server. Used by the instant updates.

function refreshSidebar() {
	
	total = _rawBookmarks.length
	
	let allTags 	= [],
		noTag 		= i18n.t('app:sidebar.filter.untagged', 'un-tagged')
	
	for( let item of _rawBookmarks ) {
		
		let uniqueTags = Array.from( new Set( item.tags ) )
		if( uniqueTags.length < 1 ) { uniqueTags.push( noTag ) }
		
		for( let tagitem of uniqueTags ) {
			allTags.push( tagitem )
		}
	}
	
	buildTagList( allTags.sort(), noTag )
	buildFolderStrip()
}



//note(dgmid): ============================================================
// CARD GRID VIEW — alternate rendering of the filtered bookmarks.
// The DataTable stays the single source of truth (data, filters, selection);
// the grid mirrors the currently filtered + sorted rows and loads preview
// screenshots lazily from the Nextcloud server with a local disk cache.
// ============================================================

let _gridMode 		= store.get( 'viewMode' ) === 'grid',
	_gridIdxMap 	= new Map(),		// bookmark id -> DataTable data index (filtered view)
	_previewObserver = null,
	_gridLastIdx 	= null,
	_gridLastSig 	= null			// signature of the last rendered row set (skip no-op rebuilds)

function getDomain( url ) {
	
	try {
		return new URL( url ).hostname.replace( /^www\./, '' )
	} catch( e ) {
		return ''
	}
}

function gridDataIndex( id ) {
	
	let table = maintable.bookmarkTable,
		found = null
	
	table.rows().every( function( rowIdx ) {
		
		if( found === null && this.data()[0] === id ) found = rowIdx
	})
	
	return found
}

function updateGridSelection() {
	
	let table 	= maintable.bookmarkTable,
		selected = new Set( table.rows({ selected: true }).indexes().toArray() )
	
	$( '#bookmark-grid .bm-card' ).each( function() {
		
		let idx = _gridIdxMap.get( parseInt( $(this).data( 'id' ), 10 ) )
		$(this).toggleClass( 'selected', ( idx != null ) && selected.has( idx ) )
	})
}

function setGridThumb( el, src ) {
	
	$(el).html( `<img class="bm-preview" src="${src}" alt="">` )
}

function setGridFallback( el, id, url ) {
	
	let fav = previews.getFaviconUrl( id )
	
	$(el).html( `<div class="bm-thumb-fallback">
		${ fav ? `<img class="bm-favicon" src="${fav}" width="24" height="24" alt="">` : '' }
		<span class="bm-domain">${ entities.encode( getDomain( url ) ) }</span>
	</div>` )
}

function loadGridThumb( el ) {
	
	let id 		= parseInt( $(el).data( 'id' ), 10 ),
		url 	= $(el).data( 'url' ) || '',
		cached 	= previews.getPreviewPath( id, url )
	
	if( cached ) {
		
		setGridThumb( el, 'file://' + encodeURI( cached ) )
		return
	}
	
	previews.fetchPreview( id, url ).then( file => {
		
		if( file ) setGridThumb( el, 'file://' + encodeURI( file ) )
		else setGridFallback( el, id, url )
	}).catch( () => setGridFallback( el, id, url ) )
}

function observeGridThumbs() {
	
	if( !( 'IntersectionObserver' in window ) ) {
		
		$( '#bookmark-grid .bm-thumb' ).each( function() { loadGridThumb( this ) } )
		return
	}
	
	if( !_previewObserver ) {
		
		_previewObserver = new IntersectionObserver( function( entries ) {
			
			for( let en of entries ) {
				
				if( en.isIntersecting ) {
					
					_previewObserver.unobserve( en.target )
					loadGridThumb( en.target )
				}
			}
		}, { root: document.getElementById( 'bookmark-grid' ), rootMargin: '200px' } )
	}
	
	$( '#bookmark-grid .bm-thumb' ).each( function() {
		_previewObserver.observe( this )
	})
}

function refreshGridView() {
	
	if( !_gridMode ) return
	
	let table 	= maintable.bookmarkTable,
		rows 	= table.rows({ search: 'applied', order: 'current' }).data().toArray(),
		indexes = table.rows({ search: 'applied', order: 'current' }).indexes().toArray()
	
	//note(dgmid): skip no-op rebuilds (e.g. a draw that didn't change the row set)
	//so already-loaded previews aren't torn down and re-observed on every keystroke
	let sig = indexes.join( ',' )
	
	if( sig === _gridLastSig ) {
		
		updateGridSelection()
		return
	}
	
	_gridLastSig = sig
	_gridIdxMap.clear()
	
	let html = ''
	
	for( let i = 0; i < rows.length; i++ ) {
		
		let r 		= rows[i],
			id 		= r[0],
			title 	= entities.decode( String( r[2] || '(untitled)' ).replace( /<[^>]*>/g, '' ) ),
			url 	= r[4] || ''
		
		_gridIdxMap.set( id, indexes[i] )
		
		html += `<div class="bm-card" data-id="${id}" data-url="${entities.encode( url )}">
			<div class="bm-thumb" data-id="${id}" data-url="${entities.encode( url )}">
				<span class="bm-loading"></span>
			</div>
			<div class="bm-info">
				<div class="bm-title" title="${entities.encode( title )}">${entities.encode( title )}</div>
				<div class="bm-domain">${entities.encode( getDomain( url ) )}</div>
			</div>
		</div>`
	}
	
	let $grid = $( '#bookmark-grid' )
	
	$grid.html( html )
	
	//note(dgmid): only show the empty message once real data has loaded — before the
	//first fetch completes the empty grid shouldn't claim there are no bookmarks
	if( rows.length === 0 && table.rows().count() > 0 ) {
		
		$grid.append( `<div class="grid-empty">` + i18n.t( 'app:view.empty', 'No bookmarks match the current filters.' ) + `</div>` )
	}
	
	updateGridSelection()
	observeGridThumbs()
}

//note(dgmid): keep the grid in sync with every table draw (search, folder, tags, sort)

maintable.bookmarkTable.on( 'draw.dt', function() {
	
	if( _gridMode ) refreshGridView()
})

//note(dgmid): keep card highlight in sync with table selection

maintable.bookmarkTable.on( 'select.dt deselect.dt', function() {
	
	if( _gridMode ) updateGridSelection()
})

//note(dgmid): card interactions — click selects (synced with the table), double-click opens

$('#bookmark-grid').on( 'click', '.bm-card', function( e ) {
	
	let table = maintable.bookmarkTable,
		id 	= parseInt( $(this).data( 'id' ), 10 ),
		idx = gridDataIndex( id )
	
	if( idx === null ) return
	
	if( e.ctrlKey || e.metaKey ) {
		
		let node = table.rows( idx ).nodes()[0]
		
		if( node && $(node).hasClass( 'selected' ) ) {
			table.rows( idx ).deselect()
		} else {
			table.rows( idx ).select()
		}
		
	} else if( e.shiftKey && _gridLastIdx !== null ) {
		
		let indexes = table.rows({ search: 'applied', order: 'current' }).indexes().toArray(),
			a = indexes.indexOf( _gridLastIdx ),
			b = indexes.indexOf( idx )
		
		if( a !== -1 && b !== -1 ) {
			
			let from = Math.min( a, b ),
				to 	= Math.max( a, b )
			
			table.rows().deselect()
			table.rows( indexes.slice( from, to + 1 ) ).select()
		}
		
	} else {
		
		table.rows().deselect()
		table.rows( idx ).select()
	}
	
	_gridLastIdx = idx
})

$('#bookmark-grid').on( 'dblclick', '.bm-card', function() {
	
	let url = $(this).data( 'url' )
	
	if( url ) shell.openExternal( url )
})

//note(dgmid): view toggle — list (table) ⇄ cards (grid), persisted in settings

