//note(dgmid): populate folder menu — render as collapsible tree view

function buildFolderList( folders ) {
	
	$('#folderlist').empty()
	
	// Build a tree structure from the flat list using parent_folder
	function buildTree( flatList ) {
		
		let map = {},
		    roots = []
		
		// First pass: index by id
		for( let f of flatList ) {
			map[ f.id ] = { id: f.id, text: f.text, parent_folder: f.parent_folder, children: [] }
		}
		
		// Second pass: build parent-child relationships
		for( let f of flatList ) {
			
			if( f.parent_folder && f.parent_folder !== -1 && map[ f.parent_folder ] ) {
				
				map[ f.parent_folder ].children.push( map[ f.id ] )
				
			} else {
				
				roots.push( map[ f.id ] )
			}
		}
		
		// Sort alphabetically at each level (locale-aware: accents, Ñ, case)
		function sortTree( nodes ) {
			
			nodes.sort( _cmpNameObjects )
			
			for( let n of nodes ) {
				if( n.children.length ) sortTree( n.children )
			}
		}
		sortTree( roots )
		
		return roots
	}
	
	// Render tree recursively as nested <ul>/<li>
	function renderTree( nodes, depth ) {
		
		if( !nodes || nodes.length === 0 ) return ''
		
		let html = '<ul class="folder-tree">'
		
		for( let node of nodes ) {
			
			let hasChildren = node.children && node.children.length > 0
			
			html += `<li class="folder-tree-item${hasChildren ? ' has-children' : ''}" data-folder-id="${node.id}">`
			
			if( hasChildren ) {
				html += `<span class="folder-toggle" style="left:${6 + depth * 18}px;"></span>`
			}
			
			html += `<a href="#" class="filter folder" data-id="${node.id}" data-filter="${node.id}" data-name="${escape(node.text)}" draggable="true" style="padding-left:${30 + depth * 18}px;background-position:left ${16 + depth * 18}px top 5px;">${node.text}</a>`
			
			if( hasChildren ) {
				html += renderTree( node.children, depth + 1 )
			}
			
			html += '</li>'
		}
		
		html += '</ul>'
		return html
	}
	
	let tree = buildTree( folders )
	let html = renderTree( tree, 0 )
	$('#folderlist').html( html )
	
	//note(dgmid): re-apply the ⌘/Ctrl multi-selection highlight after every re-render
	for( let id of _multiSel ) {
		
		let a = $(`#folderlist .filter.folder[data-id="${id}"]`)
		if( a.length ) a.addClass( 'multiselected' )
	}
}


//note(dgmid): expand/collapse folder tree toggle

$('#folderlist').on('click', '.folder-toggle', function(e) {
	
	e.stopPropagation()
	e.preventDefault()
	
	$(this).closest('.folder-tree-item').toggleClass('collapsed')
})



//note(dgmid): folder strip — subfolders of the current selection shown above the table.
//Cards can be clicked to navigate, dragged to be moved into another folder, and act
//as drop targets for bookmarks (and for other folders).

//note(dgmid): ⌘/Ctrl multi-selection of sidebar folders — highlighted rows can be
//dragged together into another folder (or Home) in one go.

let _multiSel = new Set()

function clearFolderMultiSel() {
	
	_multiSel.clear()
	$('#folderlist .filter.folder').removeClass( 'multiselected' )
}

function toggleFolderMultiSel( id, el ) {
	
	if( _multiSel.has( id ) ) {
		
		_multiSel.delete( id )
		el.removeClass( 'multiselected' )
		
	} else {
		
		_multiSel.add( id )
		el.addClass( 'multiselected' )
	}
}

let _dragType = null,		// 'folder' | 'bookmark'
	_dragId = null,
	_dragIds = null,		// whole ⌘/Ctrl selection being dragged at once
	_dragInvalid = null,	// Set of folder ids that can't accept a folder drop (itself + descendants)
	_justDragged = false	// guards the click handler right after a drag/drop



//note(dgmid): direct children of a folder (roots when parentId === -1), sorted by name

function getFolderChildren( folders, parentId ) {
	
	let isRoot = ( parentId === -1 )
	
	return folders
		.filter( f => {
			
			let parent = ( f.parent_folder == null || f.parent_folder === -1 || f.parent_folder === '-1' ) ? -1 : f.parent_folder
			
			return isRoot ? ( parent === -1 ) : ( parent === parentId )
		})
		.sort( _cmpNameObjects )
}



//note(dgmid): number of bookmarks directly inside each folder (from the DataTable, col 9)

function getFolderCounts() {
	
	let counts = new Map()
	
	try {
		
		maintable.bookmarkTable.rows().every(function() {
			
			let folderIds = this.data()[9]
			
			if( !folderIds ) return
			
			for( let id of String(folderIds).split(',') ) {
				
				let n = parseInt( id, 10 )
				counts.set( n, (counts.get( n ) || 0) + 1 )
			}
		})
		
	} catch( e ) {
		
		log.error( 'folder strip: count failed: ' + e.message )
	}
	
	return counts
}



//note(dgmid): render the strip.
//All Bookmarks → no strip at all, just the bookmarks.
//Home → root folders (no Home card, since we're already at Home).
//A folder → Home card + Subfolders label + its direct children cards.

function buildFolderStrip() {
	
	let folders 	= store.get( 'folders' ) || [],
		current 	= getCurrentFolder(),
		isAll 		= $('#filter-all .filter.all').hasClass( 'selected' ),
		isHomeView 	= $('#folder-home .filter.folder-home').hasClass( 'selected' ),
		html 		= ''
	
	//note(dgmid): All Bookmarks — just the bookmarks, with a Home shortcut up top
	//so navigation doesn't require jumping to the sidebar (also serves as a drop zone)
	if( isAll ) {
		
		html = `<div class="folder-card home" data-id="-1" title="${i18n.t( 'app:folderstrip.homehint', 'Move to Home (root)' )}">
					<span class="fc-icon"></span>
					<span class="fc-name">${i18n.t( 'app:button.home', 'Home' )}</span>
				</div>`
		
		$('#folder-strip')
			.html( html )
			.addClass( 'visible' )
		return
	}
	
	//note(dgmid): children of the current folder (roots when viewing Home)
	let children = getFolderChildren( folders, current )
	
	//note(dgmid): Home drop zone — hidden when viewing the Home folder itself
	if( !isHomeView ) {
		
		html += `<div class="folder-card home" data-id="-1" title="${i18n.t( 'app:folderstrip.homehint', 'Move to Home (root)' )}">
					<span class="fc-icon"></span>
					<span class="fc-name">${i18n.t( 'app:button.home', 'Home' )}</span>
				</div>`
	}
	
	if( children.length > 0 ) {
		
		//note(dgmid): counts only needed when cards are rendered
		let counts = getFolderCounts()
		
		html += `<span class="strip-label">${i18n.t( 'app:folderstrip.label', 'Subfolders' )}</span>`
		
		html += `<div class="subfolder-cards">`
		
		for( let folder of children ) {
			
			html += `<div class="folder-card" data-id="${folder.id}" draggable="true" title="${entities.encode( folder.text )}">
						<span class="fc-icon"></span>
						<span class="fc-name">${entities.encode( folder.text )}</span>
						<span class="fc-count">${counts.get( folder.id ) || 0}</span>
					</div>`
		}
		
		html += `</div>`
	}
	
	$('#folder-strip')
		.html( html )
		.addClass( 'visible' )
}



//note(dgmid): select a folder from the strip — syncs the sidebar and filters the table

function selectFolderById( id ) {
	
	id = parseInt( id, 10 )
	
	if( id === -1 ) {
		
		$('#folder-home .filter.folder-home').trigger( 'click' )
		return
	}
	
	let anchor = $(`#folderlist .filter.folder[data-id="${id}"]`)
	
	if( anchor.length ) {
		
		//note(dgmid): reveal the folder if it sits inside a collapsed subtree
		anchor.parents( '.folder-tree-item.collapsed' ).removeClass( 'collapsed' )
		
		//note(dgmid): scroll the sidebar so the selected folder is visible without manual scrolling
		try {
			anchor[0].scrollIntoView( { block: 'nearest' } )
		} catch( _e ) {}
		
		anchor.trigger( 'click' )
	}
}



//note(dgmid): full refresh after a move (same pattern as the other move/delete actions)

//note(dgmid): background reconciliation — re-read folders + all bookmarks from the
//server WITHOUT the blocking loader overlay and WITHOUT clearing the table up front.
//The current view stays interactive while the request is in flight; when the data
//arrives, parseBookmarks swaps the rows in a single batched pass.

function refreshAll() {
	
	showSync()
	
	fetch.bookmarksApi( 'folders', '', '', function() {
		
		fetch.bookmarksApi( 'all', '', '', function( array ) {
			
			if( !Array.isArray( array ) ) {
				
				//note(dgmid): fetch failed (callback receives null) — don't crash
				//parseBookmarks and don't leave the sync indicator spinning forever
				hideSync()
				return
			}
			
			parseBookmarks( array )
		})
	})
}



//note(dgmid): move a folder into another folder (or Home)

function moveFolder( folderId, parentId ) {
	
	moveFolderBulk( [ folderId ], parentId )
}

//note(dgmid): move several folders at once (multi-selection drag). Each folder is
//re-parented with its own API call, but the tree refreshes once, when the last one
//finishes — and the ⌘/Ctrl selection is cleared after the move.

function moveFolderBulk( ids, parentId ) {
	
	if( !ids || !ids.length ) return
	
	let folders = store.get( 'folders' ) || [],
		pending = ids.length,
		done = function() {
			
			if( --pending <= 0 ) refreshAll()
		}
	
	for( let folderId of ids ) {
		
		let folder = folders.find( f => f.id === folderId )
		
		if( !folder ) { done(); continue }
		
		let data = '?' + serialize.serialize({
			
			'title': folder.text,
			'parent_folder': parentId
		})
		
		fetch.bookmarksApi( 'renamefolder', folderId, data, done )
	}
	
	clearFolderMultiSel()
}



//note(dgmid): move a bookmark into a folder (replaces its whole folder assignment)

function moveBookmarkToFolder( bookmarkId, folderId ) {
	
	let data = '?record_id=' + bookmarkId + '&folders[]=' + folderId
	
	//note(dgmid): instant local update — the modify call replaces the whole folder
	//assignment, so we can update the single row right away (no re-download).
	fetch.bookmarksApi( 'modify', bookmarkId, data, function() {
		
		let bm = _rawBookmarks.find( b => b.id === bookmarkId )
		
		if( bm ) {
			bm.folders = [ folderId ]
			updateBookmarkRowLocal( bm )
		}
	})
}



//note(dgmid): strip events — click navigates, drag & drop moves

$('#folder-strip').on( 'click', '.folder-card', function() {
	
	//note(dgmid): ignore the click that Chromium may fire right after a drop
	if( _justDragged ) return
	
	selectFolderById( $(this).data( 'id' ) )
})

$('#folder-strip').on( 'dragstart', '.folder-card', function( e ) {
	
	let id = parseInt( $(this).data( 'id' ), 10 )
	
	_dragType 	= 'folder'
	_dragId 	= id
	_dragInvalid = folderList.getDescendants( store.get( 'folders' ) || [], id )
	_dragInvalid.add( id )
	
	e.originalEvent.dataTransfer.setData( 'text/plain', 'folder:' + id )
	e.originalEvent.dataTransfer.effectAllowed = 'move'
	
	$(this).addClass( 'dragging' )
})

$('#folder-strip').on( 'dragend', '.folder-card', function() {
	
	clearDragState()
})

//note(dgmid): sidebar tree rows are drag sources too — dragging a row that belongs
//to a ⌘/Ctrl selection moves the whole selection together.

$('#folderlist').on( 'dragstart', '.filter.folder', function( e ) {
	
	if( _justDragged ) return
	
	let id = parseInt( $(this).data( 'id' ), 10 )
	
	let ids
	if( _multiSel.has( id ) ) {
		
		ids = Array.from( _multiSel )
		
	} else {
		
		clearFolderMultiSel()
		ids = [ id ]
	}
	
	let folders = store.get( 'folders' ) || [],
		invalid = new Set( ids )
	
	for( let x of ids ) {
		
		for( let d of folderList.getDescendants( folders, x ) ) invalid.add( d )
	}
	
	_dragType 	= 'folder'
	_dragId 	= id
	_dragIds 	= ids
	_dragInvalid = invalid
	
	e.originalEvent.dataTransfer.setData( 'text/plain', 'folder:' + ids.join( ',' ) )
	e.originalEvent.dataTransfer.effectAllowed = 'move'
	
	$(this).addClass( 'dragging' )
})

$('#folderlist').on( 'dragend', '.filter.folder', function() {
	
	clearDragState()
})

$('#bookmarks tbody').on( 'dragstart', 'tr', function( e ) {
	
	let row = maintable.bookmarkTable.row( this )
	
	if( !row.data() ) return
	
	let id = row.data()[0]
	
	_dragType 	= 'bookmark'
	_dragId 	= id
	_dragInvalid = null
	
	e.originalEvent.dataTransfer.setData( 'text/plain', 'bookmark:' + id )
	e.originalEvent.dataTransfer.effectAllowed = 'move'
	
	$(this).addClass( 'dragging' )
})

$('#bookmarks tbody').on( 'dragend', 'tr', function() {
	
	clearDragState()
})

$('#folder-strip').on( 'dragover', '.folder-card', function( e ) {
	
	if( _dragType === null ) return
	
	e.preventDefault()
	e.originalEvent.dataTransfer.dropEffect = 'move'
	
	setDragFeedback( $(this), parseInt( $(this).data( 'id' ), 10 ) )
})

$('#folder-strip').on( 'dragleave', '.folder-card', function( e ) {
	
	//note(dgmid): only clear when the pointer leaves the card itself
	if( !$(this).has( e.relatedTarget ).length && e.relatedTarget !== this ) {
		
		$(this).removeClass( 'drag-over invalid' )
	}
})

$('#folder-strip').on( 'drop', '.folder-card', function( e ) {
	
	e.preventDefault()
	e.stopPropagation()
	
	handleFolderDrop( parseInt( $(this).data( 'id' ), 10 ) )
})


//note(dgmid): shared drop-target helpers (strip cards + sidebar tree)

function setDragFeedback( targetEl, targetId ) {
	
	targetEl.removeClass( 'drag-over invalid' )
	
	if( _dragType === 'folder' && _dragInvalid && _dragInvalid.has( targetId ) ) {
		
		targetEl.addClass( 'invalid' )
		
	} else {
		
		targetEl.addClass( 'drag-over' )
	}
}

function handleFolderDrop( targetId ) {
	
	let type 	= _dragType,
		id 		= _dragId,
		invalid = _dragInvalid
	
	clearDragState()
	
	if( type === 'folder' ) {
		
		let ids = ( _dragIds && _dragIds.length ) ? Array.from( _dragIds ) : ( id != null ? [ id ] : [] )
		
		//note(dgmid): nothing moves when the target is one of the dragged folders
		//themselves or a folder inside their subtree (invalid set built on dragstart)
		if( !ids.length || invalid == null || invalid.has( targetId ) ) return
		
		moveFolderBulk( ids, targetId )
		
	} else if( type === 'bookmark' && id != null ) {
		
		moveBookmarkToFolder( id, targetId )
	}
}


//note(dgmid): sidebar folder tree — also a drop target for bookmarks and folders

$('.folderlist').on( 'dragover', '.filter.folder', function( e ) {
	
	if( _dragType === null ) return
	
	e.preventDefault()
	e.originalEvent.dataTransfer.dropEffect = 'move'
	
	setDragFeedback( $(this), parseInt( $(this).data( 'id' ), 10 ) )
})

$('.folderlist').on( 'dragleave', '.filter.folder', function( e ) {
	
	//note(dgmid): only clear when the pointer leaves the item itself
	if( !$(this).has( e.relatedTarget ).length && e.relatedTarget !== this ) {
		
		$(this).removeClass( 'drag-over invalid' )
	}
})

$('.folderlist').on( 'drop', '.filter.folder', function( e ) {
	
	e.preventDefault()
	e.stopPropagation()
	
	handleFolderDrop( parseInt( $(this).data( 'id' ), 10 ) )
})

function clearDragState() {
	
	_dragType 	= null
	_dragId 	= null
	_dragInvalid = null
	
	_justDragged = true
	setTimeout( () => { _justDragged = false }, 300 )
	
	$('#folder-strip .folder-card').removeClass( 'dragging drag-over invalid' )
	$('.folderlist .filter.folder').removeClass( 'drag-over invalid dragging' )
	$('#bookmarks tbody tr.dragging').removeClass( 'dragging' )
}


//note(dgmid): get list of tags with count

function buildTagList( array, noTag ) {
	
	$('.taglist').html( '' )
	
	let compressed = [],
	copy = array.slice(0)
	
	for (var i = 0; i < array.length; i++) {
	
		var myCount = 0
		
		for (var w = 0; w < copy.length; w++) {
			
			if (array[i] == copy[w]) {
				
				myCount++
				delete copy[w]
			}
		}
		
		if (myCount > 0) {
			
			var a = new Object()
			a.value = array[i]
			a.count = myCount
			compressed.push(a)
		}
	}
	
	
	let results = [],
	untagged = '',
	brokenTag = '',
	count = 1
	
	for ( let tagitem of compressed ) {
		
		if( tagitem.value === noTag ) {
			
			untagged =
			
			`<dd class="margin-top">
				<a href="#" class="filter untagged" data-filter="${escape(tagitem.value)}">
					<span class="filter-icon icon-untagged"></span>
					<span class="filter-name">${entities.encode(tagitem.value)}</span>
					<span class="filter-count">${tagitem.count}</span>
				</a>
			</dd>`
		
		} else if( tagitem.value === 'broken' ) {
			
			var color = generate(tagitem.value)
			
			brokenTag =
			
			`<dd>
				<a href="#" class="filter tagfilter" data-id="${count}" data-filter="${entities.encode(tagitem.value)}">

						<span class="tag" title="${entities.encode(tagitem.value)}" style="background-color: ${color};">${entities.encode(tagitem.value)}</span> <span class="filter-name">${entities.encode(tagitem.value)}</span>

					<span class="filter-count">${tagitem.count}</span></a>
			</dd>`
			
			results.push( { "id": count , "text": tagitem.value } )
			count++
		
		} else {
			
			var color = generate(tagitem.value)
			
			$('#taglist').append(
			
			`<dd>
				<a href="#" class="filter tagfilter" data-id="${count}" data-filter="${entities.encode(tagitem.value)}">

						<span class="tag" title="${entities.encode(tagitem.value)}" style="background-color: ${color};">${entities.encode(tagitem.value)}</span> <span class="filter-name">${entities.encode(tagitem.value)}</span>

					<span class="filter-count">${tagitem.count}</span></a>
			</dd>`
			)
			
			results.push( { "id": count , "text": tagitem.value } )
			count++
		}
	}
	
	
	store.set('tags', results )
	
	
	$('#taglist-extras').append( `${untagged}` )
	
	// Prepend 'broken' to #taglist so it sits right after 'un-tagged' (above #taglist-extras)
	// but with the same padding/styling as regular tags
	if( brokenTag ) {
		$('#taglist').prepend( brokenTag )
	}
	$('#filter-all').append(
		 `<dd>
			<a href="#" class="filter all  selected" data-filter="">
				<span class="filter-icon icon-bookmarks"></span>
				<span class="filter-name">${i18n.t('app:sidebar.filter.all','All Bookmarks')}</span>
				<span class="filter-count">${total}</span>
			</a>
		</dd>` )
	
	$('#sidebar').fadeIn( 400 )
	
	//note(dgmid): rebuilds (refresh / parse) wipe the sidebar DOM — restore the
	//multi-tag highlights and toolbar state from the persistent selection
	updateTagSelectionUI()
	updateTagToolbar()
	
	loader( 'remove' )
}



