//note(dgmid): delete bookmark

function deleteBookmark( bookmark ) {
	
	if( bookmark !== 'delete-bookmark' ) {
		
		let response = ipcRenderer.sendSync('show-message-box', {	
								message: i18n.t('app:dialog.message.deletebookmark', 'Are you sure you want to delete the bookmark {{- bookmark}}?', {bookmark: bookmark[1]}),
								detail: i18n.t('app:dialog.detail.deletebookmark', 'This operation is not reversable.'),
								buttons: [i18n.t('app:dialog.button.deletebookmark', 'Delete Bookmark'), i18n.t('app:dialog.button.cancel', 'Cancel')]
							})
			
		if( response === 0 ) {
			
			fetch.bookmarksApi('delete', bookmark[0], '', function() {
				
				//note(dgmid): instant local update — remove the row and update the sidebar
				_rawBookmarks = _rawBookmarks.filter( b => b.id !== bookmark[0] )
				removeBookmarkRowLocal( bookmark[0] )
			})
		}
	
	} else {
	
		ipcRenderer.send('show-error-box', { title: i18n.t('app:errorbox.title.deletebookmark', 'Delete Bookmark Error'), content: i18n.t('app:errorbox.content.deletebookmark', 'A bookmark must be selected in order to delete it') })
	}
}



