//note(dgmid): refresh bookmarks

ipcRenderer.on('refresh-bookmarks', (event, message) => {
	
	let server 		= store.get( 'loginCredentials.server' ),
		username 	= store.get( 'loginCredentials.username' ),
		password 	= store.get( 'loginCredentials.password' )
	
	if( server && username && password ) {
		
		//note(dgmid): after the modals (edit bookmark / auto-tag) send their result
		//back through IPC, apply it locally here instead of re-downloading all
		//bookmarks. Anything else (structural ops) falls through to a background refresh.
		
		if( message && message.action === 'edit-bookmark' && message.data && message.data.id != null ) {
			
			let pendingEdit = message.data
			
			let bm = _rawBookmarks.find( b => b.id === pendingEdit.id )
			
			if( bm ) {
				
				bm.url 			= pendingEdit.url
				bm.title 		= pendingEdit.title
				bm.description 	= pendingEdit.description
				bm.tags 		= pendingEdit.tags
				bm.folders 		= pendingEdit.folders
				
				//note(dgmid): the modal sends back the server-assigned lastmodified
				//so the Modified column refreshes instantly after an edit
				if( pendingEdit.lastmodified ) bm.lastmodified = pendingEdit.lastmodified
				
				updateBookmarkRowLocal( bm )
				
			} else {
				
				//note(dgmid): bookmark not in the local mirror — full background refresh
				refreshAll()
			}
			
			return
		}
		
		if( message && message.action === 'tag-updates' && message.data && message.data.length ) {
			
			for( let t of message.data ) {
				
				let bm = _rawBookmarks.find( b => b.id === t.id )
				
				if( bm ) {
					bm.tags = t.tags
					updateBookmarkRowLocal( bm, false )
				}
			}
			refreshSidebar()
			
			return
		}
		
		//note(dgmid): non-blocking background refresh for everything else.
		//Reset search/filters but keep the current rows visible while the new
		//data downloads — parseBookmarks swaps them in a single batched pass.
		maintable.bookmarkTable.search('').columns().search('').draw()
		refreshAll()
	}
})



