//note(dgmid): check broken links — passes the current scope (selected bookmarks, or the
//current folder) via store so the modal can check exactly that, mirroring the auto-tag
//modal. If bookmarks are selected it acts on those (selection mode); otherwise it falls
//back to the current folder's bookmarks with an optional "include subfolders" scope
//(folder mode); when neither applies it checks the whole catalogue (all mode).

ipcRenderer.on('check-broken-links', (event, message) => {
	
	// Save selected bookmarks to a temp store key for the modal to read
	// (the modal runs in a separate BrowserWindow and can't access our DataTable)
	try {
		
		let selectedRows = maintable.bookmarkTable.rows({ selected: true }).data().toArray()
		
		let selection = selectedRows.map( r => ({
			id: r[0],
			title: (r[2] || '').toString(),
			url: (r[4] || '').toString()
		}))
		
		store.set( '_brokenLinksSelection', selection )
		
	} catch( e ) {
		
		log.error( 'check-broken: failed to read selection: ' + e.message )
		store.set( '_brokenLinksSelection', [] )
	}
	
	//note(dgmid): folder-mode context — the current folder. Only built when NO bookmarks
	//are selected (selection mode doesn't need it). folderId -1 (Home / All) means the
	//whole catalogue, which the modal treats as its "all" scope.
	if( ( store.get( '_brokenLinksSelection' ) || [] ).length === 0 ) {
		
		try {
			
			let folderId 	= getCurrentFolder(),
				folderName 	= 'Home'
			
			if( folderId && folderId !== -1 ) {
				
				let folders = store.get( 'folders' ) || [],
					f 		= folders.find( x => x.id === folderId )
				
				if( f ) folderName = f.text
			}
			
			store.set( '_brokenLinksContext', { folderId: folderId, folderName: folderName } )
			
		} catch( e ) {
			
			log.error( 'check-broken: failed to read folder context: ' + e.message )
			store.set( '_brokenLinksContext', { folderId: -1, folderName: 'Home' } )
		}
	}
	
	modalWindow.openModal( 'file://' + __dirname + '/../html/check-broken-links.html', 480, 480, false )
})



