//note(dgmid): learn folder structure with AI — analyzes how the current folder's
//subfolders are organized and saves the deduced criterion as a reusable profile

ipcRenderer.on('learn-folder-structure', (event, message) => {
	
	let folderId 	= getCurrentFolder(),
		folderName 	= 'Home',
		folders 	= store.get( 'folders' ) || []
	
	if( folderId !== -1 ) {
		
		let folder 	= folders.find( x => x.id === folderId )
		
		if( folder ) folderName = folder.text
	}
	
	let children 	= getFolderChildren( folders, folderId )
	
	//note(dgmid): per-folder stats (count + sample titles) from the DataTable — col 2 = title, col 9 = folders
	let stats = new Map()
	
	try {
		
		maintable.bookmarkTable.rows().every(function() {
			
			let title 		= entities.decode( String( this.data()[2] || '' ).replace( /<[^>]*>/g, '' ) ).trim(),
				folderStr 	= this.data()[9]
			
			if( !folderStr ) return
			
			for( let idStr of String( folderStr ).split( ',' ) ) {
				
				let fid = parseInt( idStr, 10 )
				if( !Number.isInteger( fid ) ) continue
				
				if( !stats.has( fid ) ) stats.set( fid, { count: 0, samples: [] } )
				
				let entry = stats.get( fid )
				entry.count++
				if( entry.samples.length < 5 && title ) entry.samples.push( title )
			}
		})
		
	} catch( e ) {
		
		log.error( 'learn-structure: failed to read table: ' + e.message )
	}
	
	//note(dgmid): collect the user's tag vocabulary from the folder's bookmarks
	let tagMap = new Map()
	
	try {
		
		let rawData = bookmarks.get( 'data' ) || []
		
		for( let bm of rawData ) {
			
			let bmFolders = Array.isArray( bm.folders ) ? bm.folders : []
			if( !bmFolders.includes( folderId ) ) continue
			
			let tags = Array.isArray( bm.tags ) ? bm.tags : []
			
			for( let t of tags ) {
				
				let tag = String( t ).trim().toLowerCase()
				if( !tag ) continue
				
				if( !tagMap.has( tag ) ) tagMap.set( tag, { count: 0, examples: [] } )
				
				let entry = tagMap.get( tag )
				entry.count++
				if( entry.examples.length < 3 && bm.title ) entry.examples.push( String( bm.title ).substring( 0, 80 ) )
			}
		}
		
	} catch( e ) {
		
		log.error( 'learn-structure: failed to read raw bookmarks: ' + e.message )
	}
	
	let tagExamples = [ ...tagMap.entries() ]
		.sort( (a, b) => b[1].count - a[1].count )
		.slice( 0, 20 )
		.map( ([ tag, v ]) => ({ tag, count: v.count, examples: v.examples }) )
	
	let childList = children.map( c => {
		
		let s = stats.get( c.id ) || { count: 0, samples: [] }
		
		return { name: c.text, count: s.count, samples: s.samples }
	})
	
	store.set( '_learnStructureContext', {
		folderId: folderId,
		folderName: folderName,
		children: childList,
		tagExamples: tagExamples
	})
	
	modalWindow.openModal( 'file://' + __dirname + '/../html/learn-structure.html', 480, 540, false )
})



ipcRenderer.on('load-tray-menu', (event, message) => {
	
	ipcRenderer.send( 'tray-menu', '' )
})




//note(dgmid): search

ipcRenderer.on('find', (event, message) => {
	
	$('#search').focus()
})



//note(dgmid): window state

ipcRenderer.on('state', (event, message) => {
	
	if( message === 'blur' ) {
		
		$('body').addClass( 'blurred' )
		
	} else {
		
		$('body').removeClass( 'blurred' )
	}
})



//note(dgmid): info panel width

function setPanelWidth() {
	
	if( $('td[colspan]') ) {
	
		let cols = maintable.bookmarkTable.columns().visible().toArray()
		let count = cols.filter(Boolean).length
		$('td[colspan]').attr( 'colspan', count )
	}
}



//note(dgmid): set column checkboxes

function setColControls() {
	
	let cols = store.get('tableColumns')
	
	for (let col in cols) {
		
		$(`#${col}`).prop('checked', cols[col])
		
	}
	
	// Default favicon to checked if not stored
	if( $('#favicon').length && cols.favicon === undefined ) {
		$('#favicon').prop('checked', true)
	}
}



//note(dgmid): htmlentities

function htmlEntities( str ) {
	
	return 	String(str)
			.replace(/</g, '&lt;')
			.replace(/>/g, '&gt;')
}



//note(dgmid): open info panel link in default browser
	
$('body').on('click', '.details-panel a', function(event) {
	
	event.preventDefault()
	
	let link = $(this).attr( 'href' )
	shell.openExternal(link)
})



//note(dgmid): open update link in default browser

$('body').on('click', '#update', (event) => {
	
	event.preventDefault()
	
	let link = $('#update').attr( 'data-url' )
	
	shell.openExternal(link)
})



//note(dgmid): search

$('#search').bind( 'keyup', function() {
	
	let str = $(this).val(),
		state = ( str.length > 0 ) ? $('#clear').show() : $('#clear').hide()
})


$('#clear').click(function() {
	
	//note(dgmid): only the text search lives here — the multi-tag filter is a
	//DataTable search plugin driven by the AND/OR toolbar, so leave it untouched
	$(this).hide()
	$('#search').val('')
	maintable.bookmarkTable.search( '' ).columns.adjust().responsive.recalc().draw()
})


window.onkeydown = function(e) {
  if (e.keyCode == 32 && e.target == document.body) {
    e.preventDefault()
  }
};



//note(dgmid): loader

function loader( string  ) {
	
	if( string === 'add'  ) {
		
		$('main #loader').remove()
		$('main').append('<div id="loader"></div>')
	
	} else {
		
		$('#loader').fadeOut(400, function() { $(this).remove() } )
	}
}



// ============================================================
